ALTER TABLE `pl_applications` MODIFY `status` ENUM('DRAFT', 'SUBMITTED', 'PLATFORM_REJECTED', 'ALLOCATION_PENDING', 'LENDER_ALLOCATED', 'LENDER_REVIEW', 'PENDING_CREDIT_REVIEW', 'LENDER_APPROVED', 'LENDER_REJECTED', 'ASSESSMENT_FEE_PAID') NOT NULL DEFAULT 'DRAFT';

ALTER TABLE `customers` MODIFY `onboarding_status` ENUM('MOBILE_VERIFIED', 'BASIC_DETAILS_PENDING', 'PAN_VERIFIED', 'EMAIL_VERIFIED', 'PLATFORM_BRE_PENDING', 'PLATFORM_ELIGIBLE', 'PLATFORM_INELIGIBLE', 'APPLICATION_IN_PROGRESS', 'APPLICATION_SUBMITTED', 'PENDING_CREDIT_REVIEW', 'LENDER_APPROVED', 'LENDER_REJECTED', 'DISBURSED') NOT NULL DEFAULT 'MOBILE_VERIFIED';
